(()=>{document.addEventListener('click',e=>{const a=e.target.closest('a[href]');if(!a||e.ctrlKey||e.metaKey||e.shiftKey||e.altKey)return;const raw=a.getAttribute('href'),clean=raw.split('?')[0].split('#')[0],file=clean.split('/').pop();let route=/^(component-[a-z0-9-]+|uav-components)\.html$/.test(file)?file.slice(0,-5):undefined;if(file==='index.html'&&raw.includes('#line-06'))route='line-06';if(file==='index.html'&&!route)route=raw.includes('#contact')?'contact':'home';if(!route||parent===window)return;const category=new URL(raw,location.href).searchParams.get('category');if(category)sessionStorage.setItem('ctuav-component-category',category);e.preventDefault();parent.postMessage({namespace:'ctuav-demo',type:'route',route},'*');});addEventListener('message',e=>{if(e.source!==parent||e.data?.namespace!=='ctuav-demo')return;if(e.data.type==='lang')document.querySelector(e.data.lang==='vi'?'#vi':'#en')?.click();if(e.data.type==='palette')document.documentElement.dataset.theme=e.data.theme;if(e.data.type==='view-active'&&!e.data.active){document.querySelectorAll('dialog[open]').forEach(d=>d.close());document.getAnimations().forEach(a=>a.finish());}});})();